import {setSquareDenimColours,SQUARE_DENIM_COLOURS} from './square-denim-outfit.js';
import * as T from './vendor/three.module.js';
import {animateCharacter} from './character.js';
import {animateActivity} from './activity-pose.js';
const SOURCE='assets/catalogue/outfit-f-square-denim.webp';
// Review-only controls. Captures come directly from the running game's WebGL
// renderer and scene. This module never reads or writes a story/save slot.
export function createOutfitReviewControls({renderer,scene,camera,player,stopInput,frameCamera}){
 const panel=document.createElement('section');panel.id='exact-outfit-review';panel.style.cssText='position:fixed;z-index:80;top:calc(66px + env(safe-area-inset-top));left:8px;width:min(430px,calc(100vw - 16px));max-height:52vh;overflow:auto;background:#eef3f8;color:#203547;border:1px solid #9bafc1;border-radius:10px;padding:10px;font:14px system-ui;box-sizing:border-box';
 panel.hidden=true;panel.style.display='none';panel.setAttribute('aria-label','Outfit reference and capture tools');
 panel.innerHTML='<button id="outfit-review-close" style="min-height:44px;float:right">Close review</button><h2 style="font-size:16px">Outfit review</h2><p>Denim_and_Everyday_Tops.png · <strong>rightmost column</strong>. The plain matching back is inferred with your permission. Visual direction approved; fabric clarity review pending.</p><img loading="lazy" src="'+SOURCE+'" alt="Selected charcoal square-neck top and washed-black jeans, cropped from your original reference" style="width:100%;height:auto"><p>These controls use the actual game character and scene. Walk normally or inspect a pose. Capture downloads the source beside all four rendered views.</p><div id="outfit-review-buttons" style="display:flex;flex-wrap:wrap;gap:6px"></div><p id="outfit-review-status" role="status"></p>';
 document.body.appendChild(panel);const toggle=document.createElement('button');toggle.id='outfit-review-toggle';toggle.textContent='Review';toggle.setAttribute('aria-controls',panel.id);toggle.setAttribute('aria-expanded','false');toggle.style.cssText='min-height:44px';(document.getElementById('quick-menu')||document.body).appendChild(toggle);
 const buttons=panel.querySelector('#outfit-review-buttons'),status=panel.querySelector('#outfit-review-status');let mode=null,snapshot=null,capturing=false;
 function setOpen(open){if(capturing)return;panel.hidden=!open;panel.style.display=open?'block':'none';toggle.setAttribute('aria-expanded',String(open));if(open){stopInput();if(document.getElementById('menu-toggle')?.getAttribute('aria-expanded')==='true')document.getElementById('menu-toggle').click();panel.querySelector('#outfit-review-close').focus();}else{release();(document.getElementById('menu-toggle')||toggle).focus();}}
 toggle.onclick=()=>setOpen(panel.hidden);panel.querySelector('#outfit-review-close').onclick=()=>setOpen(false);panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();setOpen(false);}});
 function select(value){if(player().userData.appearance?.outfitReview!=='square-denim-v2'){status.textContent='Reopen the single-outfit review to restore the selected prototype before capturing.';return false;}stopInput();if(!snapshot){const m=player();snapshot={position:m.position.clone(),rotation:m.rotation.clone(),fov:camera.fov};}mode=value;pose(0);return true;}
 function release(){if(snapshot){const m=player();m.position.copy(snapshot.position);m.rotation.copy(snapshot.rotation);camera.fov=snapshot.fov;camera.updateProjectionMatrix();animateCharacter(m,0,false);}mode=null;snapshot=null;stopInput();}
 function pose(dt){if(!mode)return;const m=player();m.position.copy(snapshot.position);m.rotation.set(0,0,0);if(mode==='seated'){m.position.y+=.63;animateActivity(m,'sit',dt,1);}else animateCharacter(m,dt,false);}
 function frame(){if(!mode)return;const m=player(),target=m.getWorldPosition(new T.Vector3());target.y-=mode==='seated'?.63:0;target.y+=1.15;const angle=({front:0,side:Math.PI/2,back:Math.PI,seated:.65})[mode],distance=4.9*Math.max(1,.65/camera.aspect);camera.fov=32;camera.updateProjectionMatrix();const desired=target.clone().add(new T.Vector3(Math.sin(angle)*distance,.05,Math.cos(angle)*distance));frameCamera(target,desired);camera.updateMatrixWorld();}
 for(const [id,label] of [['front','Front'],['side','Side'],['back','Back · inferred'],['seated','Seated'],['walk','Walk normally']]){const b=document.createElement('button');b.id='outfit-view-'+id;b.textContent=label;b.style.cssText='min-height:44px;padding:8px 12px';b.onclick=()=>{if(capturing)return;if(id==='walk')setOpen(false);else select(id);status.textContent=id==='walk'?'Normal movement restored.':label+' · live game view; not an exact-match claim.';};buttons.appendChild(b);}
 const colourRow=document.createElement('div');colourRow.style.cssText='display:flex;flex-wrap:wrap;gap:10px;margin:10px 0';
 for(const [slot,label] of [['shirt','Top colour'],['bottom','Jeans colour']]){
  const wrap=document.createElement('label'),input=document.createElement('input');wrap.textContent=label+' ';input.type='color';input.id='outfit-colour-'+slot;input.value=SQUARE_DENIM_COLOURS[slot];input.style.cssText='width:52px;min-height:44px';input.oninput=()=>{const m=player();setSquareDenimColours(m,{...(m.userData.outfitColours||SQUARE_DENIM_COLOURS),[slot]:input.value});status.textContent='Preview colours only; your saved looks are unchanged.';};wrap.appendChild(input);colourRow.appendChild(wrap);
 }
 const reset=document.createElement('button');reset.textContent='Reference colours';reset.style.cssText='min-height:44px';reset.onclick=()=>{setSquareDenimColours(player());for(const slot of ['shirt','bottom'])colourRow.querySelector('#outfit-colour-'+slot).value=SQUARE_DENIM_COLOURS[slot];};colourRow.appendChild(reset);buttons.appendChild(colourRow);
 const capture=document.createElement('button');capture.id='outfit-review-capture';capture.textContent='Download source + four game views';capture.style.cssText='min-height:44px;padding:8px 12px';buttons.appendChild(capture);
 capture.onclick=async()=>{if(capturing)return;capturing=true;capture.disabled=true;const previous=mode,size=renderer.getSize(new T.Vector2()),ratio=renderer.getPixelRatio(),aspect=camera.aspect;try{
  const image=new Image();image.src=SOURCE;await image.decode();const output=document.createElement('canvas');output.width=1620;output.height=1600;const c=output.getContext('2d');c.fillStyle='#eaf0f5';c.fillRect(0,0,1620,1600);const ih=Math.min(900,516*image.height/image.width),iw=ih*image.width/image.height;c.drawImage(image,12+(516-iw)/2,90,iw,ih);c.fillStyle='#203547';c.font='bold 22px Arial';c.fillText('ORIGINAL SOURCE · RIGHTMOST OUTFIT',12,40,516);c.font='18px Arial';c.fillText('Denim_and_Everyday_Tops.png',12,68,516);for(const [i,line] of ['Actual game WebGL captures','Plain matching back: inferred','Approved direction · clarity review pending','Batch 1 · independently mixable garments',new Date().toISOString()].entries())c.fillText(line,12,1040+i*30,516);
  renderer.setPixelRatio(1);renderer.setSize(540,750,false);camera.aspect=540/750;for(const [i,id] of ['front','side','back','seated'].entries()){if(!select(id))throw Error('The selected outfit prototype is not equipped.');pose(0);frame();renderer.shadowMap.needsUpdate=true;renderer.render(scene,camera);const x=540+(i%2)*540,y=Math.floor(i/2)*800;c.fillStyle='#203547';c.font='bold 22px Arial';c.fillText(id==='back'?'BACK · INFERRED CONSTRUCTION':id.toUpperCase(),x+12,y+30);c.drawImage(renderer.domElement,x,y+45,540,750);}
  const a=document.createElement('a');a.download='square-denim-actual-game-four-views.png';a.href=output.toDataURL('image/png');a.click();status.textContent='Downloaded the original source beside four captures from this game renderer. Review differences before approval.';
 }catch(error){status.textContent='Capture failed: '+error.message;}finally{renderer.setPixelRatio(ratio);renderer.setSize(size.x,size.y,false);camera.aspect=aspect;if(previous)select(previous);else release();camera.updateProjectionMatrix();capturing=false;capture.disabled=false;}};
 return {get active(){return !!mode||!panel.hidden;},pose,frame,release,panel,toggle};
}
